def choose_move(observation):
    width = observation['grid_width']
    height = observation['grid_height']
    x, y = observation['self_position']
    resources = observation['resources']
    obstacles = set((ox, oy) for ox, oy in observation['obstacles'])
    opponent_x, opponent_y = observation['opponent_position']

    # Helper to check if a position is within bounds and not an obstacle
    def valid(pos):
        px, py = pos
        return 0 <= px < width and 0 <= py < height and (px, py) not in obstacles

    # Directions with their vectors
    directions = {
        'up': (0, -1),
        'down': (0, 1),
        'left': (-1, 0),
        'right': (1, 0)
    }
    # Sorted directions by proximity to resources or opponent
    def sorted_dirs(target_x, target_y):
        return sorted(directions.items(), key=lambda d: abs(d[1][0] + x - target_x) + abs(d[1][1] + y - target_y))

    # If resources available, move closer to closest resource
    if resources:
        target = min(resources, key=lambda r: abs(r['x'] - x) + abs(r['y'] - y))
        for dir_name, (dx, dy) in sorted_dirs(target['x'], target['y']):
            nx, ny = x + dx, y + dy
            if valid((nx, ny)):
                return [dx, dy]

    # Else, move towards opponent
    for dir_name, (dx, dy) in sorted_dirs(opponent_x, opponent_y):
        nx, ny = x + dx, y + dy
        if valid((nx, ny)):
            return [dx, dy]

    # If no move towards resources or opponent is valid, try any valid move
    for dx, dy in directions.values():
        nx, ny = x + dx, y + dy
        if valid((nx, ny)):
            return [dx, dy]
    # No valid move, stay in place
    return [0, 0]
